1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	
4	const BASE_PREMIUM: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: 25,
10	  moonstone: 25,
11	};
12	
13	interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	
22	const SURCHARGE_RATES: ReadonlyArray<{ applies: (item: Item) => boolean; rate: number }> = [
23	  { applies: (item) => item.cursed === true, rate: 0.5 },
24	  { applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD, rate: 0.3 },
25	];
26	
27	const itemSurcharge = (item: Item): number => {
28	  const base = BASE_PREMIUM[item.type] ?? 0;
29	  const totalRate = SURCHARGE_RATES
30	    .filter(({ applies }) => applies(item))
31	    .reduce((sum, { rate }) => sum + rate, 0);
32	  return base * totalRate;
33	};
34	
35	const itemsSurcharge = (items: Item[]): number =>
36	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
37	
38	interface QuoteStep {
39	  op: "quote";
40	  items: Item[];
41	}
42	
43	interface Scenario {
44	  customer: { yearsWithMHPCO: number };
45	  steps: QuoteStep[];
46	}
47	
48	interface QuoteResult {
49	  premium: number;
50	}
51	
52	interface ScenarioResult {
53	  results: QuoteResult[];
54	}
55	
56	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
57	const COMPONENT_BLOCK_SIZE = 3;
58	const COMPONENT_BLOCK_BASE = 60;
59	
60	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
61	
62	const groupCountsByType = (items: Item[]): Map<string, number> => {
63	  const counts = new Map<string, number>();
64	  for (const item of items) {
65	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
66	  }
67	  return counts;
68	};
69	
70	const typeBasePremium = (type: string, count: number): number => {
71	  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
72	    return COMPONENT_BLOCK_BASE;
73	  }
74	  return BASE_PREMIUM[type] * count;
75	};
76	
77	const itemsBasePremium = (items: Item[]): number =>
78	  [...groupCountsByType(items)].reduce(
79	    (total, [type, count]) => total + typeBasePremium(type, count),
80	    0,
81	  );
82	
83	const quotePremium = ({ items }: QuoteStep): number => {
84	  const base = itemsBasePremium(items);
85	  const firstInsuranceSurcharge = base * FIRST_INSURANCE_RATE;
86	  return roundUpInMHPCOsFavor(base + itemsSurcharge(items) + firstInsuranceSurcharge + PROCESSING_FEE);
87	};
88	
89	export const runScenario = (scenario: Scenario): ScenarioResult => ({
90	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
91	});
